{
  "title": "The Rescue of the Lost Realm",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Crumbling stone gates loom under a grey sky, with faded royal banners hanging limp. Thorn vines snake through cracks in the walls.",
      "characters": ["Elara", "Kael", "Maren"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople warn the party of a curse.",
      "visual_description": "Huddled villagers in tattered clothes whisper in a narrow alley, pointing toward a distant twisted tower. Dust motes float in dim light.",
      "characters": ["Elara", "Kael", "Maren", "Town Elder", "Villagers"]
    },
    {
      "scene_number": 3,
      "caption": "The party enters the cursed tower to find the first clue.",
      "visual_description": "A spiral staircase of black stone ascends into darkness. Strange runes pulse on the walls. A single glowing feather lies on a step.",
      "characters": ["Elara", "Kael", "Maren"]
    },
    {
      "scene_number": 4,
      "caption": "A magical door blocks their path with a riddle.",
      "visual_description": "A massive door of silver-blue metal, etched with constellations, hovers slightly above the floor. Cold mist seeps from its edges.",
      "characters": ["Elara", "Kael", "Maren"]
    },
    {
      "scene_number": 5,
      "caption": "Kael solves the riddle; the door opens to a library.",
      "visual_description": "The door dissolves into shimmering light, revealing a vast circular library with floating books and a pedestal holding a crystal key.",
      "characters": ["Elara", "Kael", "Maren"]
    },
    {
      "scene_number": 6,
      "caption": "Armored patrols discover the party in the library.",
      "visual_description": "Four animated suits of armor clank into the room, visors glowing red, swords drawn. Books scatter as the party takes cover.",
      "characters": ["Elara", "Kael", "Maren", "Animated Armors"]
    },
    {
      "scene_number": 7,
      "caption": "Maren uses a distraction to slip past the guards.",
      "visual_description": "Maren kicks a shelf, sending a cascade of tomes onto the floor. The armors turn as she darts into the shadows, grabbing the crystal key.",
      "characters": ["Elara", "Kael", "Maren", "Animated Armors"]
    },
    {
      "scene_number": 8,
      "caption": "The party ascends the tower and finds a dragon's lair.",
      "visual_description": "The top of the tower is open to the sky. Bones and treasure litter the floor. A great red dragon sleeps coiled around a golden throne.",
      "characters": ["Elara", "Kael", "Maren", "Red Dragon"]
    },
    {
      "scene_number": 9,
      "caption": "Elara negotiates with the dragon for safe passage.",
      "visual_description": "Elara steps forward, hands open. The dragon opens one molten eye, smoke curling from its nostrils. A tense silence fills the chamber.",
      "characters": ["Elara", "Kael", "Maren", "Red Dragon"]
    },
    {
      "scene_number": 10,
      "caption": "The dragon reveals the captive is held in the royal palace.",
      "visual_description": "The dragon gestures with a claw toward a distant spire visible from the tower top. Banners with a broken crown flutter there.",
      "characters": ["Elara", "Kael", "Maren", "Red Dragon"]
    },
    {
      "scene_number": 11,
      "caption": "The party crosses a crumbling courtyard under patrol fire.",
      "visual_description": "Arrow slits in walls release volleys of arrows. The party sprints between fallen pillars, shields raised, dust exploding around them.",
      "characters": ["Elara", "Kael", "Maren", "Archer Guards"]
    },
    {
      "scene_number": 12,
      "caption": "They find a hidden passage behind an old royal banner.",
      "visual_description": "A tattered banner of gold and crimson hangs on a blank wall. Kael pulls it aside, revealing a narrow stone staircase going down.",
      "characters": ["Elara", "Kael", "Maren"]
    },
    {
      "scene_number": 13,
      "caption": "The passage leads to the palace dungeons.",
      "visual_description": "Damp corridors lined with cells. Torches flicker. At the end, a single cell with a glowing rune on its door holds the captive princess.",
      "characters": ["Elara", "Kael", "Maren", "Princess Lyra"]
    },
    {
      "scene_number": 14,
      "caption": "Maren picks the lock while Elara wards off guards.",
      "visual_description": "Maren kneels at the cell door, tools in hand. Elara stands guard, casting a shimmering barrier. Footsteps echo from the hall.",
      "characters": ["Elara", "Kael", "Maren", "Princess Lyra", "Palace Guards"]
    },
    {
      "scene_number": 15,
      "caption": "The group escapes the dungeons as alarms sound.",
      "visual_description": "Bells ring throughout the palace. The party and Lyra run up the stairs, torches blown out by magical wind, shadows leaping.",
      "characters": ["Elara", "Kael", "Maren", "Princess Lyra"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the final bridge, but it is guarded.",
      "visual_description": "A long stone bridge spans a chasm of mist. On the far side, a dozen armored soldiers stand ready. Behind, pursuit closes in.",
      "characters": ["Elara", "Kael", "Maren", "Princess Lyra", "Bridge Guards", "Pursuing Guards"]
    },
    {
      "scene_number": 17,
      "caption": "Kael triggers a collapse to block the pursuers.",
      "visual_description": "Kael hurls a flask of alchemical fire at the bridge supports. Stone groans and crumbles, cutting off the chasing guards as the party races forward.",
      "characters": ["Elara", "Kael", "Maren", "Princess Lyra", "Pursuing Guards"]
    },
    {
      "scene_number": 18,
      "caption": "The party crosses the bridge and escapes the city.",
      "visual_description": "The last step onto solid ground. The ruined city looms behind them, smoke rising. Dawn breaks over the hills ahead. The group shares a weary smile.",
      "characters": ["Elara", "Kael", "Maren", "Princess Lyra"]
    }
  ]
}

